package com.knowplugins.ysubz.kaoscore.bukkit.utils.disguise;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class SkinMatrix {

    private static final List<SkinData> SKINS = new ArrayList<>();
    private static final Random RANDOM = new Random();

    static {
        // Skin 1 - 6b9e962f
        SKINS.add(new SkinData("", ""));
        // Skin 2 - d9852d90
        SKINS.add(new SkinData("", ""));
        // Skin 3 - 2c50754c
        SKINS.add(new SkinData("", ""));
        // Skin 4 - e0eef150
        SKINS.add(new SkinData("", ""));
        // Skin 5 - 186d6cfa
        SKINS.add(new SkinData("", ""));
        // Skin 6 - c9e74fb9
        SKINS.add(new SkinData("", ""));
        // Skin 7 - 7cc5be21
        SKINS.add(new SkinData("", ""));
        // Skin 8 - d078ed67
        SKINS.add(new SkinData("", ""));
        // Skin 9 - 99827cbd
        SKINS.add(new SkinData("", ""));
    }

    public static SkinData getRandomSkin() {
        return SKINS.get(RANDOM.nextInt(SKINS.size()));
    }

    public static SkinData getDeterministicSkin(String key) {
        if (SKINS.isEmpty()) {
            return null;
        }
        String s = key == null ? "" : key.toLowerCase();
        int index = (s.hashCode() & 0x7fffffff) % SKINS.size();
        return SKINS.get(index);
    }

    public static class SkinData {
        public final String value, signature;
        public SkinData(String v, String s) { this.value = v; this.signature = s; }
    }
}
